/**
 * Generates src/core/language-index.js from the installed highlight.js version.
 * Run with `npm run languages` after upgrading highlight.js.
 */
import { writeFile } from 'node:fs/promises';
import { listLanguages } from './languages.js';

const languages = listLanguages();
const body = languages
  .map(({ name, aliases }) => `  ${JSON.stringify(name)}: ${JSON.stringify(aliases.join(' '))},`)
  .join('\n');

const source = `// @ts-check
// Generated by scripts/generate-language-index.js — do not edit by hand.
/**
 * Every highlight.js language name, mapped to its space-separated aliases.
 * Used to validate \`language\` attributes before any lazy import.
 *
 * @module core/language-index
 */

/** @type {Readonly<Record<string, string>>} */
export const LANGUAGE_INDEX = Object.freeze({
${body}
});
`;

await writeFile(new URL('../src/core/language-index.js', import.meta.url), source);
console.log(`language-index.js: ${languages.length} languages`);
